import { useEffect, type RefObject } from "react";

const FOCUSABLE_SELECTOR = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled])",
  "select:not([disabled])",
  "textarea:not([disabled])",
  '[tabindex]:not([tabindex="-1"])',
].join(",");

/**
 * Traps Tab focus within `ref` while `active`, moving focus into the container
 * on activate and restoring it to the previously-focused element on deactivate.
 * Use for modal dialogs and menus (BottomDrawer, the MobileBottomNav menu).
 *
 * The container should be focusable as a fallback (give it `tabIndex={-1}`) for
 * the case where it has no focusable children yet.
 *
 * `initialFocus` controls where focus lands on activate:
 * - `'first'` (default): the first focusable child -- right for menus, where
 *   the user is about to act on an item.
 * - `'container'`: the container itself -- right for form drawers, so opening
 *   one does NOT auto-focus a text field and pop the mobile keyboard (which
 *   obscures the rest of the form). The container still receives focus for
 *   screen readers; Tab then reaches the fields.
 */
export function useFocusTrap(
  ref: RefObject<HTMLElement | null>,
  active: boolean,
  options?: { initialFocus?: "first" | "container" },
): void {
  const initialFocus = options?.initialFocus ?? "first";
  useEffect(() => {
    if (!active) return;
    const container = ref.current;
    if (!container) return;

    const previouslyFocused = document.activeElement as HTMLElement | null;

    const focusable = () =>
      Array.from(
        container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR),
      ).filter((el) => el.offsetParent !== null || el === document.activeElement);

    // Move focus into the container.
    if (initialFocus === "container") {
      container.focus();
    } else {
      (focusable()[0] ?? container).focus();
    }

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key !== "Tab") return;
      const items = focusable();
      if (items.length === 0) {
        e.preventDefault();
        return;
      }
      const first = items[0];
      const last = items[items.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    };

    document.addEventListener("keydown", onKeyDown, true);
    return () => {
      document.removeEventListener("keydown", onKeyDown, true);
      // Restore focus to whatever was focused before the trap activated.
      previouslyFocused?.focus?.();
    };
  }, [active, ref, initialFocus]);
}
